CREATE OR REPLACE FUNCTION zukan_reject_row_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = '55000'; END; $$; CREATE TABLE IF NOT EXISTS zukan_predicate_definitions ( predicate_uri TEXT NOT NULL, predicate_version INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'active', value_type TEXT NOT NULL, value_schema JSONB NOT NULL DEFAULT '{}'::jsonb, cardinality TEXT NOT NULL, polarity_mode TEXT NOT NULL, temporal_profile TEXT NOT NULL, authority_profile JSONB NOT NULL DEFAULT '{}'::jsonb, external_mappings JSONB NOT NULL DEFAULT '[]'::jsonb, superseded_by_uri TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (predicate_uri, predicate_version), CHECK (predicate_version >= 1), CHECK (status IN ('proposed', 'active', 'deprecated', 'retired')), CHECK (value_type IN ('string', 'number', 'boolean', 'date', 'datetime', 'geometry', 'reference', 'json')), CHECK (cardinality IN ('one', 'many')), CHECK (polarity_mode IN ('positive_only', 'positive_or_negative')), CHECK (temporal_profile IN ('atemporal', 'valid_time', 'observation_time', 'bitemporal')), CHECK (jsonb_typeof(external_mappings) = 'array') ); DROP TRIGGER IF EXISTS trg_zukan_predicate_definitions_no_update ON zukan_predicate_definitions; CREATE TRIGGER trg_zukan_predicate_definitions_no_update BEFORE UPDATE OR DELETE ON zukan_predicate_definitions FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation(); CREATE TABLE IF NOT EXISTS zukan_value_artifacts ( artifact_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), content_object_id UUID REFERENCES zukan_content_objects(content_object_id) ON DELETE SET NULL, value_json JSONB, value_text TEXT, content_sha256 TEXT, storage_locator TEXT, availability_status TEXT NOT NULL DEFAULT 'available', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), redacted_at TIMESTAMPTZ, CHECK (availability_status IN ('available', 'suppressed', 'redacted', 'erased', 'missing')), CHECK (content_sha256 IS NULL OR content_sha256 ~ '^[0-9a-f]{64}$'), CHECK ( availability_status NOT IN ('redacted', 'erased') OR (value_json IS NULL AND value_text IS NULL AND storage_locator IS NULL) ) ); CREATE INDEX IF NOT EXISTS idx_zukan_value_artifacts_content_object ON zukan_value_artifacts (content_object_id, availability_status) WHERE content_object_id IS NOT NULL; CREATE TABLE IF NOT EXISTS zukan_claims ( claim_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), subject_id UUID NOT NULL REFERENCES zukan_subject_identities(subject_id) ON DELETE RESTRICT, predicate_uri TEXT NOT NULL, predicate_version INTEGER NOT NULL, tenant_id TEXT NOT NULL, workspace_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), FOREIGN KEY (predicate_uri, predicate_version) REFERENCES zukan_predicate_definitions(predicate_uri, predicate_version) ON DELETE RESTRICT ); CREATE INDEX IF NOT EXISTS idx_zukan_claims_subject_predicate ON zukan_claims (subject_id, predicate_uri, predicate_version, created_at DESC); CREATE TABLE IF NOT EXISTS zukan_claim_revisions ( claim_revision_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), claim_id UUID NOT NULL REFERENCES zukan_claims(claim_id) ON DELETE RESTRICT, revision INTEGER NOT NULL, predicate_uri TEXT NOT NULL, predicate_version INTEGER NOT NULL, value_artifact_id UUID REFERENCES zukan_value_artifacts(artifact_id) ON DELETE RESTRICT, asserted_by_subject_id UUID REFERENCES zukan_subject_identities(subject_id) ON DELETE SET NULL, polarity TEXT NOT NULL DEFAULT 'positive', valid_from TIMESTAMPTZ, valid_to TIMESTAMPTZ, observed_at TIMESTAMPTZ, recorded_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), publication_time TIMESTAMPTZ, recorded_sequence BIGINT GENERATED ALWAYS AS IDENTITY UNIQUE, visibility TEXT NOT NULL DEFAULT 'private', supersedes_claim_revision_id UUID REFERENCES zukan_claim_revisions(claim_revision_id) ON DELETE SET NULL, revision_metadata JSONB NOT NULL DEFAULT '{}'::jsonb, UNIQUE (claim_id, revision), CHECK (revision >= 1), CHECK (polarity IN ('positive', 'negative')), CHECK (visibility IN ('private', 'workspace', 'restricted', 'public_candidate', 'public')), CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to > valid_from), FOREIGN KEY (predicate_uri, predicate_version) REFERENCES zukan_predicate_definitions(predicate_uri, predicate_version) ON DELETE RESTRICT ); CREATE INDEX IF NOT EXISTS idx_zukan_claim_revisions_watermark ON zukan_claim_revisions (recorded_sequence, recorded_at); CREATE INDEX IF NOT EXISTS idx_zukan_claim_revisions_claim ON zukan_claim_revisions (claim_id, revision DESC); CREATE INDEX IF NOT EXISTS idx_zukan_claim_revisions_predicate_time ON zukan_claim_revisions (predicate_uri, predicate_version, observed_at DESC, recorded_sequence DESC); CREATE OR REPLACE FUNCTION zukan_validate_claim_revision_append() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE parent_claim zukan_claims%ROWTYPE; expected_revision INTEGER; BEGIN SELECT * INTO parent_claim FROM zukan_claims WHERE claim_id = NEW.claim_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'claim_not_found' USING ERRCODE = '23503'; END IF; IF NEW.predicate_uri <> parent_claim.predicate_uri OR NEW.predicate_version <> parent_claim.predicate_version THEN RAISE EXCEPTION 'claim_predicate_mismatch' USING ERRCODE = '23514'; END IF; SELECT COALESCE(MAX(revision), 0) + 1 INTO expected_revision FROM zukan_claim_revisions WHERE claim_id = NEW.claim_id; IF NEW.revision <> expected_revision THEN RAISE EXCEPTION 'zukan_claim_revision_must_append_expected_%', expected_revision USING ERRCODE = '23514'; END IF; RETURN NEW; END; $$; DROP TRIGGER IF EXISTS trg_zukan_claim_revisions_validate_append ON zukan_claim_revisions; CREATE TRIGGER trg_zukan_claim_revisions_validate_append BEFORE INSERT ON zukan_claim_revisions FOR EACH ROW EXECUTE FUNCTION zukan_validate_claim_revision_append(); DROP TRIGGER IF EXISTS trg_zukan_claim_revisions_no_update ON zukan_claim_revisions; CREATE TRIGGER trg_zukan_claim_revisions_no_update BEFORE UPDATE OR DELETE ON zukan_claim_revisions FOR EACH ROW EXECUTE FUNCTION zukan_reject_row_mutation();
